// Package ratelimit implements a concurrency-safe token-bucket rate limiter
// with an injectable clock for deterministic testing.
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by the system time.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// It is safe for concurrent use by multiple goroutines.
type Limiter struct {
	mu        sync.Mutex
	clock     Clock
	rate      float64   // tokens per second
	burst     int       // bucket capacity
	tokens    float64   // current tokens
	last      time.Time // last refill time
}

// New creates a Limiter that refills at rate tokens per second, with a
// maximum burst capacity. Both must be positive.
func New(ratePerSec float64, burst int, clock Clock) (*Limiter, error) {
	if ratePerSec <= 0 {
		return nil, fmt.Errorf("rate must be positive, got %v", ratePerSec)
	}
	if burst <= 0 {
		return nil, fmt.Errorf("burst must be positive, got %v", burst)
	}
	if clock == nil {
		return nil, errors.New("clock must not be nil")
	}
	return &Limiter{
		clock:  clock,
		rate:   ratePerSec,
		burst:  burst,
		tokens: float64(burst),
		last:   clock.Now(),
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are consumed.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(float64(l.burst), l.tokens+elapsed*l.rate)
		l.last = now
	}
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// RetryAfter returns the duration until n tokens would be available,
// or 0 if they are available now. n must be non-negative.
func (l *Limiter) RetryAfter(n int) time.Duration {
	if n < 0 {
		return -1
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	need := float64(n) - l.tokens
	if need <= 0 {
		return 0
	}
	return time.Duration(need / l.rate * float64(time.Second))
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
