		{"zero rate", 0, 1, newFakeClock(time.Unix(0, 0)), true},
		{"negative rate", -1, 1, newFakeClock(time.Unix(0, 0)), true},
		{"zero burst", 1, 0, newFakeClock(time.Unix(0, 0)), true},
		{"negative burst", 1, -5, newFakeClock(time.Unix(0, 0)), true},
